import assert from 'node:assert/strict';
import test from 'node:test';
import fs from 'node:fs';
import crypto from 'node:crypto';
import ts from 'typescript';
import {z} from 'zod';
import sharp from 'sharp';
import {createLabDatabase, LAB_FIXTURE, fixtureToken, seedLegacyLabCanaries} from '../scripts/lab-system-fixture.mjs';

const uuid=()=>crypto.randomUUID(), token=()=>crypto.randomBytes(32).toString('hex');
const digest=value=>crypto.createHash('sha256').update(value).digest('hex');
const SLOT_IDS=['8x10','5x7-a','5x7-b'];
const DEFAULT_POLICY={autoApprove:false,cropResponsibility:'photographer',labColourCorrection:false};
const LAB_POLICY={autoApprove:true,cropResponsibility:'lab',labColourCorrection:true};
const OLD_TABLES=['schools','projects','packages','package_profiles','orders','studio_labs','studio_lab_catalog','lab_price_sheets','lab_order_assets','lab_orders','lab_order_events','in_house_price_sheets','in_house_test_galleries','in_house_test_orders','in_house_test_order_events','lab_production_policies','lab_production_assets','lab_production_galleries','lab_production_jobs','lab_production_events'];
function load(file,deps={}){const code=ts.transpileModule(fs.readFileSync(new URL('../'+file,import.meta.url),'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022,esModuleInterop:true}}).outputText;const exports={};new Function('require','exports',code)(name=>{if(!(name in deps))throw Error('Missing dependency '+name);return deps[name];},exports);return exports;}
const money=load('lib/labs/money.ts');
const validation=load('lib/labs/validation.ts',{zod:{z},'./money':money});
const sheetValidation=load('lib/labs/in-house-validation.ts',{'node:crypto':crypto,zod:{z},'./money':money,'./validation':validation});
const v1Validation=load('lib/labs/production-validation.ts',{zod:{z},'./validation':validation});
const v2Types=load('lib/labs/production-v2-types.ts');
const v2Validation=load('lib/labs/production-v2-validation.ts',{zod:{z},'./validation':validation,'./production-validation':v1Validation,'./production-v2-types':v2Types});
function entry(patch={}){return{id:'invented-v2-private-package',sourceKey:'packages.invented-v2-private-package',section:'package',name:'Invented private retail package',retailCents:4275,active:true,category:'package',contents:[{name:'8x10 Lustre',qty:1},{name:'5x7 Lustre',qty:2}],original:{synthetic:true},...patch};}
function syntheticSheet(){const sourceSnapshot={profile:{id:'invented-v2-source-'+uuid(),name:'Invented source'},contents:entry().contents,price:4275};return{name:'Invented v2 test prices',studioName:'Invented studio',currency:'CAD',source:{profileId:sourceSnapshot.profile.id,profileName:sourceSnapshot.profile.name,contentHash:sheetValidation.inHouseSourceHash(sourceSnapshot)},entries:[entry()],warnings:[],tax:{enabled:false,percent:0,label:'Synthetic reference'},sourceSnapshot};}
async function asRole(db,role,user,fn,aal='aal2'){assert(['service_role','authenticated','anon'].includes(role));return db.transaction(async tx=>{await tx.exec('set local role '+role);await tx.query("select set_config('request.jwt.claim.sub',$1,true),set_config('request.jwt.claim.role',$2,true),set_config('request.jwt.claims',$3,true)",[user||'',role,JSON.stringify({sub:user,role,aal})]);return fn(tx);});}
async function rpc(db,name,args){assert.match(name,/^[a-z_][a-z_0-9]*$/);const entries=Object.entries(args);for(const[k]of entries)assert.match(k,/^[a-z_][a-z_0-9]*$/);return asRole(db,'service_role',null,async tx=>(await tx.query('select '+name+'('+entries.map(([k],i)=>k+'=>$'+(i+1)).join(',')+') as result',entries.map(([,v])=>v!==null&&typeof v==='object'?JSON.stringify(v):v))).rows[0].result);}
async function snapshots(db,tables=OLD_TABLES){const result={};for(const name of tables){assert.match(name,/^[a-z_][a-z_0-9]*$/);result[name]=(await db.query("select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) as rows from "+name+' t')).rows[0].rows;}return JSON.stringify(result);}
const partnerTarget=()=>({kind:'partner_lab',labId:LAB_FIXTURE.lab,product8x10Id:LAB_FIXTURE.productB,product5x7Id:LAB_FIXTURE.productA});
function originalDocument(patch={},photographer=LAB_FIXTURE.photographer){const id=uuid();return{id,kind:'original',jobId:null,size:null,sourceAssetId:null,filename:'SYNTHETIC-original-'+digest(id).slice(0,12)+'.jpg',storageKey:photographer+'/'+id+'.jpg',sha256:digest(id),byteSize:12345,widthPixels:3000,heightPixels:4200,contentType:'image/jpeg',...patch};}
async function original(db,patch={},actor=LAB_FIXTURE.owner){const document=originalDocument(patch,actor===LAB_FIXTURE.otherOwner?LAB_FIXTURE.otherPhotographer:LAB_FIXTURE.photographer);return rpc(db,'register_lab_production_asset',{p_user_id:actor,p_document:document});}
async function importSheet(db){return rpc(db,'save_in_house_price_sheet',{p_user_id:LAB_FIXTURE.owner,p_action:'import',p_id:uuid(),p_expected_version:0,p_document:syntheticSheet()});}
async function setPolicy(db,policy,version=1){return rpc(db,'save_lab_production_policy',{p_user_id:LAB_FIXTURE.owner,p_expected_version:version,p_policy:policy});}
async function makeGallery(db,options={}){const sheet=options.sheet||await importSheet(db),originals=options.originals||await Promise.all([0,1,2].map(()=>original(db))),accessToken=token();const payload={sheetId:sheet.id,expectedSheetVersion:sheet.version,entryId:entry().id,name:'SYNTHETIC independent slots',assetIds:originals.map(a=>a.id),tokenHash:digest(accessToken),target:options.target||partnerTarget()};const result=await rpc(db,'create_lab_production_gallery',{p_user_id:LAB_FIXTURE.owner,p_request_id:uuid(),p_payload:payload});return{sheet,originals,accessToken,result,id:result.id,photos:result.document.photos};}
function defaultSelections(gallery){return Object.fromEntries(SLOT_IDS.map((slot,index)=>[slot,gallery.photos[index].id]));}
async function submit(db,gallery,patch={}){const values={galleryId:gallery.id,accessToken:gallery.accessToken,requestId:uuid(),receiptToken:token(),selections:defaultSelections(gallery),quantity:2,...patch};const args={p_gallery_id:values.galleryId,p_token_hash:digest(values.accessToken),p_request_id:values.requestId,p_receipt_hash:digest(values.receiptToken),p_selections:values.selections,p_quantity:values.quantity};const result=await rpc(db,'submit_lab_production_v2_order',args);return{...values,args,result,id:result.id};}
const job=async(db,id)=>(await db.query('select * from lab_production_v2_jobs where id=$1',[id])).rows[0];
const events=async(db,id)=>(await db.query('select * from lab_production_v2_events where job_id=$1 order by version',[id])).rows;
const holds=async(db,id)=>(await db.query('select lab_production_v2_holds(j) as holds from lab_production_v2_jobs j where id=$1',[id])).rows[0].holds;
async function act(db,id,action,details={},options={}){return rpc(db,'act_lab_production_v2_job',{p_user_id:options.actor||LAB_FIXTURE.labOperator,p_job_id:id,p_expected_version:options.version??(await job(db,id)).version,p_request_id:options.requestId||uuid(),p_action:action,p_details:details});}
function rect(slot){return slot==='8x10'?{x:60,y:300,width:2880,height:3600,rotation:0}:{x:0,y:0,width:3000,height:4200,rotation:0};}
function derivedDocument(jobId,slotId,sourceAssetId,patch={}){const id=uuid();return{id,kind:'crop',jobId,slotId,sourceAssetId,filename:'SYNTHETIC-'+slotId+'.jpg',storageKey:LAB_FIXTURE.photographer+'/'+id+'.jpg',sha256:digest(id),byteSize:12345,widthPixels:slotId==='8x10'?2400:1500,heightPixels:slotId==='8x10'?3000:2100,contentType:'image/jpeg',...patch};}
async function saveCrop(db,id,slotId,options={}){const current=await job(db,id),slot=current.work.slots[slotId];const document=options.document||derivedDocument(id,slotId,slot.sourceAssetId);const args={p_user_id:options.actor||LAB_FIXTURE.owner,p_job_id:id,p_expected_version:options.version??current.version,p_request_id:options.requestId||uuid(),p_slot_id:slotId,p_crop:options.rect||rect(slotId),p_asset_document:document};return{result:await rpc(db,'save_lab_production_v2_crop',args),document,args,assetId:document.id};}
async function finishSlot(db,id,slotId,{cropActor=LAB_FIXTURE.owner,colour=false,corrected=false}={}){const crop=await saveCrop(db,id,slotId,{actor:cropActor});await act(db,id,'approve_crop',{slotId,assetId:crop.assetId},{actor:cropActor});let finalAssetId=crop.assetId;if(colour){if(corrected){const doc=derivedDocument(id,slotId,crop.assetId,{kind:'corrected'});await rpc(db,'register_lab_production_v2_asset',{p_user_id:LAB_FIXTURE.labOperator,p_document:doc});finalAssetId=doc.id;}await act(db,id,'complete_colour',{slotId,assetId:finalAssetId,reviewNoChange:!corrected});}await act(db,id,'final_review',{slotId,assetId:finalAssetId});return{...crop,finalAssetId};}
async function finishJob(db,id,options={}){await act(db,id,'accept');if(!options.autoApprove)await act(db,id,'approve_order',{}, {actor:LAB_FIXTURE.owner});for(const slot of SLOT_IDS)await finishSlot(db,id,slot,options);assert.deepEqual(await holds(db,id),[]);for(const status of ['in_production','ready','completed'])await act(db,id,'transition',{status});return job(db,id);}

// Every ID, price, school and photograph in these tests is invented.
async function seedExisting(db){
 await seedLegacyLabCanaries(db);
 const draft={name:'SYNTHETIC existing lab prices',labId:LAB_FIXTURE.lab,currency:'CAD',pricing:{markupPercent:100,rounding:'none'},items:[{catalogProductId:LAB_FIXTURE.productA,retailCents:1234,enabled:true}],packages:[],shipping:{mode:'pickup',feeCents:0,title:'Pickup'},terms:'Synthetic',assignments:[]};await rpc(db,'save_lab_price_sheet',{p_user_id:LAB_FIXTURE.owner,p_id:uuid(),p_expected_version:0,p_document:draft,p_action:'create'});
 const assetId=uuid();await db.query("insert into lab_order_assets(id,photographer_id,lab_id,filename,storage_key,sha256,width_pixels,height_pixels,content_type,byte_size,ready) values($1,$2,$3,'SYNTHETIC existing.jpg',$4,$5,600,400,'image/jpeg',120,true)",[assetId,LAB_FIXTURE.photographer,LAB_FIXTURE.lab,'synthetic-existing/'+assetId+'.jpg','c'.repeat(64)]);
 await rpc(db,'submit_lab_order',{p_actor_user_id:LAB_FIXTURE.owner,p_request_id:uuid(),p_payload:{labId:LAB_FIXTURE.lab,reference:'SYNTHETIC prior partner order',notes:'',delivery:{mode:'pickup',name:'Invented studio',address:''},items:[{catalogProductId:LAB_FIXTURE.orderProduct,assetId,quantity:1}]}});
 const sheet=await importSheet(db),legacyToken=token(),assets=[{id:'sample-8x10',filename:'SYNTHETIC-8x10.jpg',widthInches:8,heightInches:10,widthPixels:2400,heightPixels:3000,sha256:'a'.repeat(64),byteSize:1234,quantity:1},{id:'sample-5x7',filename:'SYNTHETIC-5x7.jpg',widthInches:5,heightInches:7,widthPixels:1500,heightPixels:2100,sha256:'b'.repeat(64),byteSize:1234,quantity:2}];
 const oldGallery=await rpc(db,'create_in_house_test_gallery',{p_user_id:LAB_FIXTURE.owner,p_request_id:uuid(),p_sheet_id:sheet.id,p_expected_sheet_version:sheet.version,p_entry_id:entry().id,p_name:'SYNTHETIC prior rehearsal',p_token_hash:digest(legacyToken),p_assets:assets});await rpc(db,'submit_in_house_test_order',{p_gallery_id:oldGallery.id,p_token_hash:digest(legacyToken),p_request_id:uuid(),p_receipt_hash:digest(token()),p_offer_id:oldGallery.document.offer.id,p_photo_id:'studio-os-inhouse-demo-v1',p_quantity:1});
 await setPolicy(db,DEFAULT_POLICY);const gallery=await makeGallery(db,{sheet}),receiptToken=token();await rpc(db,'submit_lab_production_order',{p_gallery_id:gallery.id,p_token_hash:digest(gallery.accessToken),p_request_id:uuid(),p_receipt_hash:digest(receiptToken),p_photo_id:gallery.photos[0].id,p_quantity:2});
}

test('v2 strict actions require all three named slots and reject client prices, extra fields and unsafe reasons',()=>{
 const base={jobId:uuid(),expectedVersion:1,requestId:uuid()};
 const parent={action:'submit',galleryId:uuid(),accessToken:token(),requestId:uuid(),receiptToken:token(),selections:{'8x10':uuid(),'5x7-a':uuid(),'5x7-b':uuid()},quantity:2};
 assert.deepEqual(v2Validation.parseProductionV2ParentAction(parent),parent);
 for(const selections of [{...parent.selections,'5x7-c':uuid()},{'8x10':uuid(),'5x7-a':uuid()},{...parent.selections,'5x7-b':'source-private-id'},null])assert.throws(()=>v2Validation.parseProductionV2ParentAction({...parent,selections}),/Choose/);
 for(const quantity of [0,11,1.5,'2',null])assert.throws(()=>v2Validation.parseProductionV2ParentAction({...parent,quantity}),/Choose/);
 for(const field of ['retailCents','subtotalMinor','printAllowed','sourceAssetId'])assert.throws(()=>v2Validation.parseProductionV2ParentAction({...parent,[field]:1}),/Choose/);
 for(const slotId of SLOT_IDS)assert.equal(v2Validation.parseProductionV2OwnerAction({action:'save_crop',...base,slotId,rect:rect(slotId)}).slotId,slotId);
 for(const slotId of ['5x7','5x7-c',null])assert.throws(()=>v2Validation.parseProductionV2OwnerAction({action:'save_crop',...base,slotId,rect:rect('5x7-a')}),/Check/);
 for(const reason of ['', 'four', 'bad\nreason', 'x'.repeat(501)])assert.throws(()=>v2Validation.parseProductionV2OwnerAction({action:'reopen',...base,reason}),/Check/);
 assert.equal(v2Validation.parseProductionV2OwnerAction({action:'reprint',...base,reason:'Synthetic reprint request',receiptToken:token()}).action,'reprint');
});

test('v2 migration preserves populated legacy tables and every existing production row byte for byte',async()=>{
 let before;const db=await createLabDatabase({beforeProductionV2Migration:async database=>{await seedExisting(database);before=await snapshots(database);}});
 try{assert(before);assert(Object.values(JSON.parse(before)).every(rows=>rows.length>0),'All twenty previous tables have actual canaries');assert.equal(await snapshots(db),before);for(const table of ['lab_production_v2_jobs','lab_production_v2_assets','lab_production_v2_events'])assert.equal((await db.query('select count(*)::int as n from '+table)).rows[0].n,0);const bucket=(await db.query("select public,file_size_limit from storage.buckets where id='lab-production-v2-files'")).rows[0];assert.equal(bucket.public,false);assert.equal(Number(bucket.file_size_limit),4000000);}finally{await db.close();}
});

test('three independent sources remain frozen while manual approval and every slot hold block production',async()=>{
 const db=await createLabDatabase();try{
  const gallery=await makeGallery(db),before=await snapshots(db),submitted=await submit(db,gallery),initial=await job(db,submitted.id),frozen=structuredClone(initial.snapshot);
  assert.deepEqual(Object.keys(initial.work.slots).sort(),[...SLOT_IDS].sort());assert.deepEqual(SLOT_IDS.map(s=>initial.work.slots[s].sourceAssetId),gallery.originals.map(a=>a.id));assert.deepEqual(initial.snapshot.initialSelections,submitted.selections);assert.equal(initial.snapshot.quantity,2);assert.equal(initial.snapshot.subtotalMinor,8550);assert.equal(initial.snapshot.testOnly,true);assert.equal(initial.snapshot.printAllowed,false);assert.equal(initial.snapshot.payment,'test_no_payment');assert.equal(initial.dispatch_state,'idle');
  assert((await holds(db,submitted.id)).includes('photographer_approval'));await act(db,submitted.id,'accept');await assert.rejects(()=>act(db,submitted.id,'transition',{status:'in_production'}),/PRODUCTION_HELD/);await assert.rejects(()=>act(db,submitted.id,'approve_order'),/PRODUCTION_FORBIDDEN/);await assert.rejects(()=>saveCrop(db,submitted.id,'8x10',{actor:LAB_FIXTURE.labOperator}),/PRODUCTION_FORBIDDEN/);
  await act(db,submitted.id,'approve_order',{}, {actor:LAB_FIXTURE.owner});const first=await finishSlot(db,submitted.id,'8x10');const second=await finishSlot(db,submitted.id,'5x7-a');assert((await holds(db,submitted.id)).includes('crop_5x7-b'));await assert.rejects(()=>act(db,submitted.id,'transition',{status:'in_production'}),/PRODUCTION_HELD/);const third=await finishSlot(db,submitted.id,'5x7-b');assert.notEqual(second.assetId,third.assetId);assert.deepEqual(await holds(db,submitted.id),[]);
  for(const status of ['in_production','ready','completed'])await act(db,submitted.id,'transition',{status});const completed=await job(db,submitted.id);assert.deepEqual(completed.snapshot,frozen);assert.deepEqual(SLOT_IDS.map(s=>completed.work.slots[s].cropAssetId),[first.assetId,second.assetId,third.assetId]);assert.equal(await snapshots(db),before,'New slot processing does not rewrite any old table or original');const receipt=await rpc(db,'read_lab_production_v2_receipt',{p_receipt_hash:digest(submitted.receiptToken)});assert.equal(receipt.status,'completed');assert.equal(receipt.printSlots.length,3);for(const hidden of [...gallery.originals.map(a=>a.id),gallery.sheet.id,entry().id,gallery.sheet.source_hash])assert(!JSON.stringify(receipt).includes(hidden));
 }finally{await db.close();}
});

test('slot submission is bounded and idempotent; source replacement is owner-only and clears only that slot',async()=>{
 const db=await createLabDatabase();try{
  const gallery=await makeGallery(db),before=await snapshots(db),submitted=await submit(db,gallery);const again=await rpc(db,'submit_lab_production_v2_order',submitted.args);assert.equal(again.id,submitted.id);assert.equal(again.replayed,true);assert.equal((await db.query('select count(*)::int n from lab_production_v2_jobs')).rows[0].n,1);
  for(const patch of [{p_quantity:3},{p_receipt_hash:digest(token())},{p_selections:{...submitted.selections,'5x7-b':gallery.photos[0].id}}])await assert.rejects(()=>rpc(db,'submit_lab_production_v2_order',{...submitted.args,...patch}),/PRODUCTION_REQUEST_CONFLICT/);
  for(const selections of [{...submitted.selections,'5x7-c':uuid()},{'8x10':gallery.photos[0].id,'5x7-a':gallery.photos[1].id},{...submitted.selections,'5x7-b':null},{...submitted.selections,'5x7-b':gallery.originals[2].id},{...submitted.selections,'5x7-b':uuid()}])await assert.rejects(()=>submit(db,gallery,{selections}),/PRODUCTION_INVALID|PRODUCTION_NOT_FOUND/);
  for(const quantity of [0,11,null])await assert.rejects(()=>submit(db,gallery,{quantity}),/PRODUCTION_INVALID/);
  const repeated=await submit(db,gallery,{selections:Object.fromEntries(SLOT_IDS.map(s=>[s,gallery.photos[0].id])),quantity:10});assert.equal(repeated.result.quantity,10);assert.equal(repeated.result.subtotalMinor,42750);assert((await job(db,repeated.id)).work.slots['5x7-b'].sourceAssetId===gallery.originals[0].id,'The same gallery photograph may deliberately fill multiple slots');
  await act(db,submitted.id,'accept');const first=await finishSlot(db,submitted.id,'8x10'),second=await finishSlot(db,submitted.id,'5x7-a');await finishSlot(db,submitted.id,'5x7-b');const previous=await job(db,submitted.id),requestId=uuid();await assert.rejects(()=>act(db,submitted.id,'set_slot_source',{slotId:'5x7-a',photoId:gallery.photos[2].id}),/PRODUCTION_FORBIDDEN/);
  const updated=await act(db,submitted.id,'set_slot_source',{slotId:'5x7-a',photoId:gallery.photos[2].id},{actor:LAB_FIXTURE.owner,requestId,version:previous.version});assert.equal(updated.work.slots['5x7-a'].sourceAssetId,gallery.originals[2].id);assert.deepEqual(updated.work.slots['8x10'],previous.work.slots['8x10']);assert.deepEqual(updated.work.slots['5x7-b'],previous.work.slots['5x7-b']);assert.equal(updated.work.slots['5x7-a'].cropApproved,false);for(const field of ['cropAssetId','cropApprovedAt','colourAssetId','colourCompletedAt','finalReviewedAt'])assert.equal(updated.work.slots['5x7-a'][field],undefined);
  assert.equal((await act(db,submitted.id,'set_slot_source',{slotId:'5x7-a',photoId:gallery.photos[2].id},{actor:LAB_FIXTURE.owner,requestId,version:previous.version})).replayed,true);await assert.rejects(()=>act(db,submitted.id,'set_slot_source',{slotId:'5x7-a',photoId:gallery.photos[1].id},{actor:LAB_FIXTURE.owner,requestId,version:previous.version}),/PRODUCTION_REQUEST_CONFLICT/);await assert.rejects(()=>act(db,submitted.id,'approve_crop',{slotId:'5x7-a',assetId:second.assetId},{actor:LAB_FIXTURE.owner}),/PRODUCTION_STALE_RENDER/);await assert.rejects(()=>act(db,submitted.id,'final_review',{slotId:'5x7-b',assetId:first.assetId}),/PRODUCTION_STALE_RENDER/);assert.equal(await snapshots(db),before);
 }finally{await db.close();}
});

test('lab-owned crops and colour review bind to the exact independent slot and retain stale-render holds',async()=>{
 const db=await createLabDatabase();try{
  await setPolicy(db,LAB_POLICY);const gallery=await makeGallery(db),submitted=await submit(db,gallery);await act(db,submitted.id,'accept');assert(!(await holds(db,submitted.id)).includes('photographer_approval'));
  const crop=await saveCrop(db,submitted.id,'5x7-a',{actor:LAB_FIXTURE.labOperator});const before=await job(db,submitted.id);await assert.rejects(()=>saveCrop(db,submitted.id,'5x7-b',{actor:LAB_FIXTURE.owner}),/PRODUCTION_FORBIDDEN/);await assert.rejects(()=>act(db,submitted.id,'complete_colour',{slotId:'5x7-a',assetId:crop.assetId,reviewNoChange:true}),/PRODUCTION_FORBIDDEN/);await act(db,submitted.id,'approve_crop',{slotId:'5x7-a',assetId:crop.assetId});
  const corrected=derivedDocument(submitted.id,'5x7-a',crop.assetId,{kind:'corrected'});await rpc(db,'register_lab_production_v2_asset',{p_user_id:LAB_FIXTURE.labOperator,p_document:corrected});await assert.rejects(()=>act(db,submitted.id,'complete_colour',{slotId:'5x7-b',assetId:corrected.id,reviewNoChange:false}),/PRODUCTION_STALE_RENDER/);await assert.rejects(()=>act(db,submitted.id,'complete_colour',{slotId:'5x7-a',assetId:corrected.id,reviewNoChange:true}),/PRODUCTION_STALE_RENDER/);await act(db,submitted.id,'complete_colour',{slotId:'5x7-a',assetId:corrected.id,reviewNoChange:false});await act(db,submitted.id,'final_review',{slotId:'5x7-a',assetId:corrected.id});
  const siblingBefore=structuredClone((await job(db,submitted.id)).work.slots['5x7-b']);const replacement=await saveCrop(db,submitted.id,'5x7-a',{actor:LAB_FIXTURE.labOperator});const changed=(await job(db,submitted.id)).work.slots['5x7-a'];assert.equal(changed.cropApproved,false);for(const field of ['cropApprovedAt','colourAssetId','colourCompletedAt','finalReviewedAt'])assert.equal(changed[field],undefined);assert.deepEqual((await job(db,submitted.id)).work.slots['5x7-b'],siblingBefore);await assert.rejects(()=>act(db,submitted.id,'approve_crop',{slotId:'5x7-a',assetId:crop.assetId}),/PRODUCTION_STALE_RENDER/);await assert.rejects(()=>rpc(db,'register_lab_production_v2_asset',{p_user_id:LAB_FIXTURE.labOperator,p_document:derivedDocument(submitted.id,'5x7-a',crop.assetId,{kind:'corrected'})}),/PRODUCTION_STALE_RENDER/);
  await act(db,submitted.id,'approve_crop',{slotId:'5x7-a',assetId:replacement.assetId});await act(db,submitted.id,'complete_colour',{slotId:'5x7-a',assetId:replacement.assetId,reviewNoChange:true});await act(db,submitted.id,'final_review',{slotId:'5x7-a',assetId:replacement.assetId});await finishSlot(db,submitted.id,'8x10',{cropActor:LAB_FIXTURE.labOperator,colour:true,corrected:true});await finishSlot(db,submitted.id,'5x7-b',{cropActor:LAB_FIXTURE.labOperator,colour:true});assert.deepEqual(await holds(db,submitted.id),[]);assert.equal((await events(db,submitted.id)).filter(e=>e.action==='reviewed_no_colour_change').length,2);assert.deepEqual((await job(db,submitted.id)).snapshot,before.snapshot);
 }finally{await db.close();}
});

