test('a completed reprint creates a linked full package with fresh holds while the old agreement and history stay exact',async()=>{
 const db=await createLabDatabase();try{
  const gallery=await makeGallery(db),submitted=await submit(db,gallery);await assert.rejects(()=>reprint(db,submitted.id),/PRODUCTION_TRANSITION/);await finishJob(db,submitted.id);const old=await job(db,submitted.id),oldEvents=await events(db,submitted.id),requestId=uuid(),receiptHash=digest(token());
  const child=await reprint(db,submitted.id,{requestId,receiptHash});assert.notEqual(child.id,old.id);assert.equal(child.reprint_of,old.id);assert.equal(child.status,'submitted');assert.equal(child.dispatch_state,'idle');assert.equal(child.version,1);assert.deepEqual(child.snapshot,old.snapshot);assert.equal(child.snapshot.quantity,2);assert.equal(child.snapshot.subtotalMinor,8550);assert.equal(child.work.photographerApproved,false);for(const s of SLOT_IDS){assert.equal(child.work.slots[s].sourceAssetId,old.work.slots[s].sourceAssetId);assert.equal(child.work.slots[s].photoId,old.work.slots[s].photoId);assert.equal(child.work.slots[s].cropApproved,false);for(const field of ['cropAssetId','colourAssetId','finalReviewedAt'])assert.equal(child.work.slots[s][field],undefined);}assert.equal((await holds(db,child.id)).length,7);assert.deepEqual(await job(db,old.id),old);assert.deepEqual(await events(db,old.id),oldEvents);
  const replayed=await reprint(db,old.id,{requestId,receiptHash,version:old.version});assert.equal(replayed.id,child.id);assert.equal(replayed.replayed,true);await assert.rejects(()=>reprint(db,old.id,{requestId,receiptHash,reason:'Different synthetic request'}),/PRODUCTION_REQUEST_CONFLICT/);await assert.rejects(()=>reprint(db,old.id,{actor:LAB_FIXTURE.otherOwner}),/PRODUCTION_NOT_FOUND/);await assert.rejects(()=>reprint(db,old.id,{actor:LAB_FIXTURE.labViewer}),/PRODUCTION_NOT_FOUND/);await assert.rejects(()=>act(db,old.id,'reopen',{reason:'Completed jobs use reprints'}),/PRODUCTION_DISPATCH_LOCKED/);
  const receipt=await rpc(db,'read_lab_production_v2_receipt',{p_receipt_hash:receiptHash});assert.equal(receipt.id,child.id);assert.equal(receipt.reprintOf,old.id);assert.equal(receipt.printSlots.length,3);assert.equal(receipt.testOnly,true);assert.equal(receipt.printAllowed,false);assert.equal(receipt.payment,'test_no_payment');await assert.rejects(()=>rpc(db,'read_lab_production_v2_receipt',{p_receipt_hash:digest(token())}),/PRODUCTION_NOT_FOUND/);
 }finally{await db.close();}
});

