async function pairDevice(db,options={}){const values={actor:LAB_FIXTURE.labOperator,kind:'partner_lab',target:LAB_FIXTURE.lab,name:'SYNTHETIC Windows connector',codeHash:digest(token()),id:uuid(),tokenHash:digest(token()),...options};await rpc(db,'create_lab_connector_pair',{p_user_id:values.actor,p_kind:values.kind,p_target:values.target,p_name:values.name,p_code_hash:values.codeHash});const args={p_code_hash:values.codeHash,p_device_id:values.id,p_token_hash:values.tokenHash};return{...values,args,result:await rpc(db,'pair_lab_connector',args)};}
async function dispatchReady(db,options={}){const gallery=await makeGallery(db,options),submitted=await submit(db,gallery);await act(db,submitted.id,'accept');await act(db,submitted.id,'approve_order',{}, {actor:LAB_FIXTURE.owner});for(const s of SLOT_IDS)await finishSlot(db,submitted.id,s);await act(db,submitted.id,'transition',{status:'in_production'});return{submitted,gallery,job:await job(db,submitted.id)};}
async function queueArgs(db,id,patch={}){const current=await job(db,id),dispatchId=uuid();const manifest={schemaVersion:2,dispatchId,jobId:id,reference:current.reference,version:current.version,testOnly:true,printAllowed:false,payment:'test_no_payment',outputProfile:'sRGB',densityPpi:300,quantity:current.snapshot.quantity,finishedPrints:current.snapshot.quantity*3,paperSheets:current.snapshot.quantity*2,sheets:[{size:'8x10',filename:current.reference+'-8x10.jpg',sha256:'a'.repeat(64),byteSize:123,widthPixels:2400,heightPixels:3000,copies:current.snapshot.quantity,printsPerSheet:1,slots:['8x10']},{size:'10x7',filename:current.reference+'-10x7.jpg',sha256:'b'.repeat(64),byteSize:234,widthPixels:3000,heightPixels:2100,copies:current.snapshot.quantity,printsPerSheet:2,slots:['5x7-a','5x7-b']}]};return{p_user_id:LAB_FIXTURE.labOperator,p_job_id:id,p_expected_version:current.version,p_request_id:uuid(),p_dispatch_id:dispatchId,p_manifest:manifest,p_manifest_sha256:digest(JSON.stringify(manifest)),...patch};}
const claim=(db,device)=>rpc(db,'claim_lab_connector_dispatch',{p_device_id:device.id,p_token_hash:device.tokenHash});
function dispatchReceipt(args){return{state:'staged_for_review',manifestSha256:args.p_manifest_sha256,files:args.p_manifest.sheets.map(s=>({name:s.filename,sha256:s.sha256,byteSize:s.byteSize}))};}
const receiptArgs=(device,args,receipt=dispatchReceipt(args))=>({p_device_id:device.id,p_token_hash:device.tokenHash,p_dispatch_id:args.p_dispatch_id,p_receipt:receipt});

