test('a revoked machine never causes an already claimed dispatch to requeue to another machine',async()=>{
 const db=await createLabDatabase();try{
  const first=await pairDevice(db),second=await pairDevice(db,{actor:LAB_FIXTURE.labOwner});const ready=await dispatchReady(db),args=await queueArgs(db,ready.job.id);await rpc(db,'queue_lab_connector_dispatch',args);assert.equal((await claim(db,first)).id,args.p_dispatch_id);await rpc(db,'revoke_lab_connector',{p_user_id:LAB_FIXTURE.labOwner,p_device_id:first.id});await assert.rejects(()=>claim(db,first),/CONNECTOR_AUTH/);assert.equal(await claim(db,second),null);const dispatch=(await db.query('select * from lab_connector_dispatches where id=$1',[args.p_dispatch_id])).rows[0];assert.equal(dispatch.device_id,first.id);assert.equal(dispatch.state,'claimed');assert.equal((await job(db,ready.job.id)).dispatch_state,'claimed');await assert.rejects(()=>rpc(db,'receipt_lab_connector_dispatch',receiptArgs(first,args)),/CONNECTOR_AUTH/);
  await db.query('update lab_memberships set active=false where lab_id=$1 and user_id=$2',[LAB_FIXTURE.lab,LAB_FIXTURE.labOperator]);await assert.rejects(()=>rpc(db,'queue_lab_connector_dispatch',args),/CONNECTOR_FORBIDDEN/);await db.query('update lab_memberships set active=true where lab_id=$1 and user_id=$2',[LAB_FIXTURE.lab,LAB_FIXTURE.labOperator]);
  for(const field of ['p_user_id','p_job_id','p_expected_version','p_request_id','p_dispatch_id'])await assert.rejects(()=>rpc(db,'queue_lab_connector_dispatch',{...args,[field]:null}),/CONNECTOR_INVALID/);
 }finally{await db.close();}
});
